      text.className = "option-text";
      text.textContent = optText;

      optLabel.append(checkbox, text);
      options.appendChild(optLabel);
    });

    field.appendChild(options);

    const errMsg = document.createElement("p");
    errMsg.className = "field-error";
    errMsg.textContent = "Please select at least one answer.";
    field.appendChild(errMsg);

    form.insertBefore(field, document.getElementById("submit-wrap"));
  });
