.option-text {
  font-size: 14.5px;
  color: var(--text-primary);
  line-height: 1.4;
}

/* ── Validation state ── */
.form-field.has-error .option-text-wrapper {
  color: var(--error);
}

.field-error {
  display: none;
  font-size: 12.5px;
  color: var(--error);
  margin-top: 12px;
  padding-left: 2px;
}

.form-field.has-error .field-error {
  display: block;
