@keyframes slideUp {
  from { opacity: 0; transform: translateY(12px); }
  to   { opacity: 1; transform: translateY(0); }
}

@media (max-width: 480px) {
  .form-field { padding: 20px 18px 18px; }
  .help-text { padding-left: 0; }
}
